            "booking-title",
            "restaurant-image",
            "restaurant-address",
            "party-size-field",
            "datetime-field",
            "dietary-field",
            "submit-button"
          ]
        },
        {
          "id": "booking-title",
          "component": "Text",
          "variant": "h2",
          "text": {
            "path": "/title"
          }
        },
        {
          "id": "restaurant-image",
          "component": "Image",
          "url": {
            "path": "/imageUrl"
          }
        },
        {
          "id": "restaurant-address",
          "component": "Text",
          "text": {
            "path": "/address"
          }
        },
        {
          "id": "party-size-field",
          "component": "TextField",
