          "variant": "number"
        },
        {
          "id": "datetime-field",
          "component": "DateTimeInput",
          "label": "Date & Time",
          "value": {
            "path": "/reservationTime"
          },
          "enableDate": true,
          "enableTime": true
        },
        {
          "id": "dietary-field",
          "component": "TextField",
          "label": "Dietary Requirements",
          "value": {
            "path": "/dietary"
          }
        },
        {
          "id": "submit-button",
          "component": "Button",
          "child": "submit-reservation-text",
          "action": {
            "event": {
              "name": "submit_booking",
              "context": {
                "restaurantName": {
                  "path": "/restaurantName"
                },
                "partySize": {
                  "path": "/partySize"
                },
                "reservationTime": {
                  "path": "/reservationTime"
                },
                "dietary": {
                  "path": "/dietary"
                },
                "imageUrl": {
                  "path": "/imageUrl"
                }
              }
            }
          }
        },
        {
