          "component": "Text",
          "text": "Submit Reservation"
        }
      ]
    }
  },
  {
    "version": "v0.9",
    "updateDataModel": {
      "surfaceId": "booking-form",
      "path": "/",
      "value": {
        "title": "Book a Table at [RestaurantName]",
