  {
    "version": "v0.9",
    "createSurface": {
      "surfaceId": "booking-form",
      "catalogId": "https://a2ui.org/specification/v0_9/catalogs/basic/catalog.json",
      "theme": {
        "primaryColor": "#FF0000",
        "font": "Roboto"
      }
    }
  },
  {
    "version": "v0.9",
    "updateComponents": {
      "surfaceId": "booking-form",
      "components": [
        {
          "id": "root",
          "component": "Column",
          "children": [
            "booking-title",
            "restaurant-image",
            "restaurant-address",
            "party-size-field",
            "datetime-field",
            "dietary-field",
            "submit-button"
          ]
        },
        {
          "id": "booking-title",
          "component": "Text",
          "variant": "h2",
          "text": {
            "path": "/title"
          }
        },
        {
          "id": "restaurant-image",
          "component": "Image",
          "url": {
            "path": "/imageUrl"
          }
        },
        {
          "id": "restaurant-address",
          "component": "Text",
          "text": {
            "path": "/address"
          }
